import { createMemo, splitProps } from "solid-js";
import { Dynamic } from "solid-js/web";
import "./Text.css";
export function Text(props) {
    const [current, rest] = splitProps(props, ["options"]);
    const customization = createMemo(() => {
        const options = Object.assign({}, {
            size: "base",
            font: "mono",
            weight: "normal",
            wrap: "wrap",
        }, current.options);
        const entries = Object.entries(options);
        return Object.fromEntries(entries.map(([key, value]) => [`data-start-text-${key}`, value]));
    });
    return (<Dynamic component={(current.options?.as || "span")} {...rest} {...customization()}/>);
}
